<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Fake Ubuntu Desktop</title>
    <style>
        :root {
            --bg-color: #2e3436; /* Dark Grey */
            --taskbar-bg: #1f2529; /* Very dark blue/grey */
            --window-header: #2c3032;
            --accent: #078aa8;
            --text-color: #eeeeee;
        }

        body, html { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; font-family: 'Ubuntu', sans-serif; background-color: var(--bg-color); color: var(--text-color); user-select: none;}

        #desktop { position: absolute; top: 0; left: 0; width: 100vw; height: 100vh; overflow: hidden; }

        /* Wallpaper area */
        .wallpaper { 
            position: absolute; bottom: 60px; left: 20px; right: 20px; top: 40px; 
            background: linear-gradient(135deg, #1a2b3c, #2e495f);
            z-index: -1; border-radius: 8px; opacity: 0.6;
        }

        /* Taskbar */
        #taskbar {
            position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%);
            background: rgba(30, 42, 48, 0.9); padding: 6px 12px; border-radius: 12px;
            display: flex; gap: 10px; box-shadow: 0 4px 6px rgba(0,0,0,0.3); z-index: 1000;
        }

        .launcher-btn {
            background-color: #5892a7; border: none; color: white; padding: 8px 16px; 
            border-radius: 4px; cursor: pointer; font-size: 14px; transition: background 0.2s;
        }
        .launcher-btn:hover { background-color: #3a7c9d; }

        /* Windows */
        .window {
            position: absolute; top: 5%; left: 20%; width: auto; min-width: 360px; 
            max-width: 80vw; height: auto; min-height: 240px; background-color: #1d1f20;
            border-radius: 8px; box-shadow: 0 10px 20px rgba(0,0,0,0.5); display: flex; 
            flex-direction: column; overflow: hidden; resize: both; color: var(--text-color);
        }

        .win-header {
            background-color: #3b4751; padding: 8px; cursor: move; /* draggable-looking */
            display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #2c3032;
        }

        .win-title { font-weight: bold; pointer-events: none;}

        button.win-close { background: #cc5454; color: white; border: none; width: 16px; height: 16px; border-radius: 50%; cursor: pointer; }

        .win-body { flex-grow: 1; padding: 0; overflow: auto; position: relative;}

        /* Files App */
        #files-path-bar { background-color: var(--taskbar-bg); padding: 8px; font-size: 14px; border-bottom: 1px solid #2c3032; display:flex; gap:5px; align-items:center;}
        .fs-item { padding: 6px; cursor: pointer; color: var(--text-color); }
        .fs-item:hover { background-color: rgba(255,255,255,0.1); }

        /* Notepad App */
        #tabs-container { display: flex; background-color: #3b4751; overflow-x:auto;}
        .tab { padding: 8px 16px; cursor: pointer; border-right: 1px solid #2c3032; font-size: 13px; min-width: 80px; text-align: center; display:flex; align-items:center; justify-content:center;}
        .tab.active { background-color: var(--accent); color: white; }

        textarea#editor { width: 100%; height: calc(100% - 45px); resize: none; border: none; padding: 8px; box-sizing: border-box; font-family: monospace; background-color: #2e3436; color: white;}

        button#new-tab { background-color: var(--accent); border:none; color:white; margin-left:auto; cursor:pointer; }

    </style>
</head>
<body>
<div id="desktop">
    <div class="wallpaper"></div>

    <!-- Taskbar -->
    <div id="taskbar">
        <button id="open-files" class="launcher-btn">Files</button>
        <button id="open-notepad" class="launcher-btn">Notepad</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window" style="display: none; top: 10%; left: 25%;">
        <div class="win-header">
            <span class="win-title">Files</span>
            <button class="win-close"></button>
        </div>
        <div id="files-path-bar" style="padding:8px; background:#3b4751;">
            <!-- Requirement: #files-path shows absolute path -->
            <span id="files-path">/</span>
            <!-- Requirement: #files-up navigates to parent -->
            <button id="files-up" disabled>&#8593; Up</button>
        </div>
        <div id="fs-list" class="win-body"></div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window" style="display: none; top: 15%; left: 30%;">
        <div class="win-header">
            <span class="win-title">Notepad</span>
            <button class="win-close"></button>
        </div>

        <!-- Requirement: #tabs holds tab strip, tabs have class .tab -->
        <div id="tabs" style="display:flex; background-color:#3b4751;">
             <!-- New Tab Button (ID not strictly defined for new-tab in HTML reqs except as control) -->
            <button id="new-tab">+ Tab</button>
        </div>

        <!-- Requirement: #editor is a textarea showing active tab content -->
        <textarea id="editor"></textarea>
    </div>
</div>

<script>
// --- File System Mock Data (Static Fake Data) ---
const fileSystem = {
    name: '/', type: 'dir', 
    children: {
        bin: { name: 'bin', type: 'file' }, // Can be dir or file, but let's make them dirs for nav testing. Req says "Double-clicking a folder navigates". I will treat all root items as folders (dirs) to ensure structure can be traversed easily like Linux directories.
        bin: { name: 'bin', type: 'dir' }, // Overridden in next block? No, JS object literal syntax requires unique keys. Let's build the object carefully below.
    }
};

// Re-defining FS for clarity and strict compliance with path requirements
const fileSystem = {};
fileSystem['/'] = { name: '/', type: 'dir', children: {} };

// Populate Root / items (must contain bin, etc, home, usr, var)
fileSystem['/'].children.bin = { name: 'bin', type: 'dir' };
fileSystem['/'].children.etc = { name: 'etc', type: 'dir' };
fileSystem['/'].children.home = { 
    name: 'home', type: 'dir', children: {} 
}; // Home contains user

// Navigate to home -> user structure (via pointer manipulation)
const rootObj = fileSystem['/'];
let h_obj = rootObj.children.home;
h_obj.children.user = { 
    name: 'user', type: 'dir', 
    children: {
        Documents: { name: 'Documents', type: 'file' }, // Req says "contains at least" + any files I like. Dirs/Folders easier to navigate? Requirement implies navigating folders works (Double-click navigates). If these are FILES, double click shouldn't navigate necessarily. But for a filesystem REPLICA it makes sense they are directories in home/user context. However, strict reading: if item is file/folder listed as entry. I will treat them as FOLDERS so they can be opened to show content or just displayed? Actually standard FS has Documents folder inside user directory usually (like `~/Documents`). So type dir fits best for "Files" app logic demonstration (nested structure).
        Documents: { name: 'Documents', type: 'dir' }, 
        Downloads: { name: 'Downloads', type: 'file' }, // Mixing types to be realistic, but only folders are navigable by double click.
        Pictures: { name: 'Pictures', type: 'dir' }
    }
};

fileSystem['/'].children.usr = { name: 'usr', type: 'dir' };
fileSystem['/'].children.var  = { name: 'var', type: 'file' }; // Var often a dir, but file is valid entry too.


// --- NOTEPAD LOGIC (Tabs & Persistence) ---
let notepadState = { activeId: null, tabs: [] };

function loadNotepad() {
    const raw = localStorage.getItem('ubuntu_notepad_tabs');
    if (raw) {
        try {
            notepadState = JSON.parse(raw);
        } catch(e) { console.error("Failed to parse tabs", e); return; }
    } else {
        // No state yet. Default empty tab array? Or create one automatically on open.
        // I'll keep it empty and let creation happen in UI logic if needed, or here for safety.
        notepadState = { activeId: null, tabs: [] };
    }
}

function saveNotepad() {
    localStorage.setItem('ubuntu_notepad_tabs', JSON.stringify(notepadState));
}

function createTab(content = '') {
    const id = Date.now().toString(); 
    notepadState.tabs.push({ id, content });
    activateTab(id);
    renderTabs(); // Re-render UI based on new state
    saveNotepad();
}

// Note: The contract says "Clicking a .tab switches to it." and "#new-tab creates new".
// It does not require closing tabs via X button, but usually good for UX. I will keep simple.

function activateTab(id) {
    if(!id) return; // no active tab case? (e.g. all deleted). Just create one automatically on load/open then?

    notepadState.activeId = id;
    saveNotepad();
    renderTabs();

    const domTab = document.querySelector(`.tab[data-id="${id}"]`);
    if(domTab) {
        // Update UI active class (handled in render usually, but explicit here for clarity)
        document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        domTab.classList.add('active');

        // Scroll tab into view if needed
        setTimeout(() => domTab.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' }), 10);
    }

    const content = getActiveTabContent();
    document.getElementById('editor').value = content || '';
}

function getActiveTabContent() {
    if(!notepadState.activeId) return '';
    const tab = notepadState.tabs.find(t => t.id == notepadState.activeId);
    return tab ? tab.content : '';
}

// Editor input listener to persist content of ACTIVE TAB immediately (or on blur). 
// Requirement: "All tabs and their content persist". Saving every keystroke ensures persistence.
document.getElementById('editor').addEventListener('input', () => {
    if(notepadState.activeId) {
        const tab = notepadState.tabs.find(t => t.id == notepadState.activeId);
        if(tab) {
            tab.content = document.getElementById('editor').value;
            saveNotepad(); // Persist immediately to ensure restore on reload works.
        }
    }
});

function renderTabs() {
    const tabsContainer = document.getElementById('tabs');
    // Keep the New Tab button at end, but it's inside #tabs container in HTML structure? 
    // The prompt says "#new-tab creates a new empty tab". ID is attached to element.

    // Clear existing dynamic tabs (but keep the button or re-append)
    const btn = document.getElementById('new-tab');
    if(btn && btn.parentElement === tabsContainer) {
        tabsContainer.removeChild(btn);
    }

    notepadState.tabs.forEach((tab, index) => {
        const div = document.createElement('div');
        div.className = 'tab';
        // Show some identifier. Let's use "Tab N" or first few chars of content? 
        // Simpler: Numbered as per previous logic works fine for text visibility.
        div.textContent = `Tab ${index + 1}`;

        if (notepadState.activeId == tab.id) {
            div.classList.add('active');
        }

        // Requirement: "Clicking a .tab switches to it."
        div.addEventListener('click', () => activateTab(tab.id));

        tabsContainer.appendChild(div);
    });

    if(btn && btn.parentElement !== tabsContainer) {
         tabsContainer.appendChild(btn);
    } else if (!btn) {
        // Fallback for safety
        tabsContainer.appendChild(document.getElementById('new-tab')); 
    }

    // Set initial active tab UI
    activateTab(notepadState.activeId || (notepadState.tabs.length > 0 ? notepadState.tabs[0].id : null));
}

// --- FILES APP LOGIC (FS Navigation) ---
let fsStack = []; // Array of names visited from root down. 
                 // e.g., [] means /. [home, user] means /home/user.
let currentFolderDict = fileSystem['/'].children; 

function initFilesApp() {
    updateFilesWindow();

    document.getElementById('files-up').addEventListener('click', () => {
        if (fsStack.length > 0) {
            // Pop last entry to go back to parent folder in history? 
            fsStack.pop(); 

            // Recalculate currentFolderDict by traversing down stack of names + root children.
            let tempRef = fileSystem['/'].children;
            for(let name of fsStack) {
                if(tempRef[name]) {
                    // If we want to handle potential missing keys gracefully:
                    const node = tempRef[name];
                    if(node && node.type === 'dir') {
                        tempRef = node.children || {}; 
                    } else break; // error path?
                } else break;
            }
            currentFolderDict = tempRef;

            updateFilesWindow();
        }
    });
}

function updateFilesWindow() {
    // Build Path String: '/' + fsStack.join('/')
    let pathStr = '/';
    if(fsStack.length > 0) {
        pathStr += fsStack.join('/');
    } else {
        pathStr = '/';
    }

    document.getElementById('files-path').textContent = pathStr;

    // Render Items from currentFolderDict
    const keys = Object.keys(currentFolderDict);

    if(keys.length === 0) {
        const el = document.createElement('div');
        el.className = 'fs-item';
        el.textContent = "Directory is empty";
        document.getElementById('fs-list').appendChild(el);
        return;
    }

    for(let key of keys) {
        // Key might not match displayed name exactly if data has different structure? 
        // In my FS object: children[key] exists. The `name` property inside the child is used as visible text.
        const node = currentFolderDict[key];

        const el = document.createElement('div');
        el.className = 'fs-item';
        el.textContent = node.name;

        if(node.type === 'dir') {
            // Double click listener for folders navigates into it (path updates).
            el.addEventListener('dblclick', () => {
                fsStack.push(key); 
                currentFolderDict = node.children || {}; 
                updateFilesWindow();
            });
        }

        document.getElementById('fs-list').appendChild(el);
    }

    if(fsStack.length > 0) {
        // Allow going up (back to parent)
        const btn = document.getElementById('files-up');
        if(btn) btn.disabled = false;

        // Restore button state from previous run?
    } else {
         const btn = document.getElementById('files-up');
         if(btn) btn.disabled = true;
    }
}

// --- Window Visibility Logic ---

function openFileWindow() {
    initFilesApp(); 
    fsStack = []; // Reset to root on open (optional behavior, but clean)
    currentFolderDict = fileSystem['/'].children;
    updateFilesWindow();

    document.getElementById('files-window').style.display = 'flex';
}

function closeFileWindow() {
    document.getElementById('files-window').style.display = 'none';
}

function openNotepadWindow() {
    loadNotepad(); // Reload state from LS
    renderTabs();

    if(notepadState.tabs.length === 0) createTab();
    else activateTab(notepadState.activeId || notepadState.tabs[0].id);

    document.getElementById('notepad-window').style.display = 'flex';
}

function closeNotepadWindow() {
    saveNotepad(); // Ensure state saved before closing
    document.getElementById('notepad-window').style.display = 'none';
}


// --- Event Listeners ---

document.getElementById('open-files').addEventListener('click', openFileWindow);
document.querySelectorAll('.win-close')[0].addEventListener('click', closeFileWindow); 

document.getElementById('open-notepad').addEventListener('click', openNotepadWindow);
document.querySelectorAll('.win-close')[1].addEventListener('click', closeNotepadWindow); 
document.querySelector('#new-tab').addEventListener('click', () => { createTab(); });

// --- Window Draggability (Polish) ---
function makeDraggable(winEl) {
    const header = winEl.querySelector('.win-header');
    if (!header) return;

    let isDragging = false;
    let dragOffsetX, dragOffsetY;

    header.onmousedown = function(e) {
        isDragging = true;
        // Calculate offset from top-left of window to mouse pointer relative to initial pos
        const rect = winEl.getBoundingClientRect();
        dragOffsetX = e.clientX - rect.left;
        dragOffsetY = e.clientY - rect.top;

        document.onmousemove = function(e) {
            if(!isDragging) return;

            let x = e.clientX - dragOffsetX;
            let y = e.clientY - dragOffsetY;

            winEl.style.left = x + 'px';
            winEl.style.top = y + 'px';
        };

        document.onmouseup = function() {
            isDragging = false;
            document.onmousemove = null;
            document.onmouseup = null;
        };
    };
}

makeDraggable(document.getElementById('files-window'));
makeDraggable(document.getElementById('notepad-window'));


// --- Initialization ---
window.onload = () => {
   // Notepad state loads on open, but we ensure FS is ready.
};

</script>
</body>
</html>
